<?php $isLive=$tab==='live';$inProgress=($test['attempt_status']??'')==='in_progress';$starts=strtotime($test['starts_at']);$ends=strtotime($test['ends_at']);$deadline=$inProgress?strtotime((string)$test['deadline_at']):null;$lastSeen=$inProgress?strtotime((string)$test['last_seen_at']):null;$remaining=($deadline&&$lastSeen)?max(0,$deadline-$lastSeen):0;?>
<article class="my-test-card card <?=$inProgress?'in-progress':''?>">
 <div class="my-test-visual"><?php if(!empty($test['thumbnail_path'])):?><img src="/cbt/media/<?=e($test['thumbnail_path'])?>" alt=""><?php else:?><span aria-hidden="true">✦</span><?php endif;?></div>
 <div class="my-test-content"><span class="my-test-state <?=$inProgress?'progress':e($tab)?>"><?=$inProgress?'IN PROGRESS':($isLive?'LIVE NOW':strtoupper(e($tab)))?></span><h3><?=e($test['title'])?></h3><p><?=e($test['subject'])?> · <?=e($test['full_marks'])?> marks · <?=e($test['duration_minutes'])?> minutes</p><?php if($isLive):?><b class="my-test-progress"><?=$inProgress?e((int)$test['saved_responses']).' of '.e((int)$test['total_questions']).' questions saved · Timer paused · Resume within 30 min':'Not started'?></b><?php elseif($tab==='upcoming'):?><b class="my-test-progress">Opens <?=e(date('d M Y, h:i A',$starts))?></b><?php else:?><b class="my-test-progress">Score: <?=e($test['obtained_marks'])?> / <?=e($test['full_marks'])?></b><?php endif;?></div>
 <aside class="my-test-action"><?php if($isLive&&$inProgress):?><span class="remaining-time"><?=e(sprintf('%02d:%02d:%02d',intdiv($remaining,3600),intdiv($remaining%3600,60),$remaining%60))?> remaining</span><form method="post" action="/cbt/exam/<?=e($test['id'])?>/start"><?=csrf_field()?><button class="btn">Resume exam →</button></form><?php elseif($isLive):?><span>Ends <?=e(date('d M, h:i A',$ends))?></span><a class="btn" href="/cbt/exam/<?=e($test['id'])?>/instructions">Start exam →</a><?php elseif($tab==='upcoming'):?><span>Starts <?=e(date('d M, h:i A',$starts))?></span><button class="btn disabled" disabled>Starts soon</button><?php else:?><span>Submitted</span><a class="btn secondary" href="/cbt/result/<?=e($test['attempt_id'])?>">◉ View result</a><?php endif;?></aside>
</article>
